    $('subStart').value=0;$('subEnd').value=Math.min(3,duration).toFixed(2);$('subText').value='';$('titleText').value='';
    $('projectName').textContent=name;$('exportName').value=name.replace(/\.[^.]+$/,'');
    $('empty').hidden=true;canvas.hidden=false;$('playBtn').disabled=false;$('muteBtn').disabled=false;$('seek').disabled=false;
    $('seek').max=duration;$('stateLabel').textContent='可開始編輯';loaded=true;committed=true;renderLists();draw();
